// Shim mínimo de multer: parsea multipart/form-data real desde el Buffer crudo de la petición.
import fs from 'node:fs';
import path from 'node:path';

function parseMultipart(buf, boundary) {
  const delim = Buffer.from(`--${boundary}`);
  const partes = [];
  let desde = buf.indexOf(delim) + delim.length;
  while (true) {
    const siguiente = buf.indexOf(delim, desde);
    if (siguiente === -1) break;
    let trozo = buf.slice(desde, siguiente);
    if (trozo.slice(0, 2).toString() === '--') break; // cierre final
    if (trozo.slice(0, 2).toString('utf8') === '\r\n') trozo = trozo.slice(2);
    if (trozo.slice(-2).toString('utf8') === '\r\n') trozo = trozo.slice(0, -2);
    const finCabeceras = trozo.indexOf('\r\n\r\n');
    if (finCabeceras !== -1) {
      const cabeceras = trozo.slice(0, finCabeceras).toString('utf8');
      const cuerpo = trozo.slice(finCabeceras + 4);
      const nombreM = cabeceras.match(/name="([^"]*)"/);
      const archivoM = cabeceras.match(/filename="([^"]*)"/);
      const tipoM = cabeceras.match(/Content-Type:\s*(.+)/i);
      partes.push({
        name: nombreM?.[1] || '', filename: archivoM ? archivoM[1] : undefined,
        mimetype: tipoM?.[1]?.trim(), data: cuerpo,
      });
    }
    desde = siguiente + delim.length;
  }
  return partes;
}

function multer(opts = {}) {
  const { storage, limits = {}, fileFilter } = opts;
  return {
    single(campo) {
      return (req, res, next) => {
        const ct = req.headers['content-type'] || '';
        const m = ct.match(/boundary=(.+)$/);
        if (!m) return next();
        const partes = parseMultipart(req._rawBody, m[1]);
        req.body = req.body || {};
        let archivo = null;
        for (const p of partes) {
          if (p.filename !== undefined) { if (p.name === campo) archivo = p; }
          else req.body[p.name] = p.data.toString('utf8');
        }
        if (!archivo) return next();
        if (limits.fileSize && archivo.data.length > limits.fileSize) {
          const err = new Error('File too large'); err.name = 'MulterError'; err.code = 'LIMIT_FILE_SIZE';
          return next(err);
        }
        const procesar = (err) => {
          if (err) return next(err);
          const destino = typeof storage.destination === 'function'
            ? (cb) => storage.destination(req, { originalname: archivo.filename }, cb)
            : (cb) => cb(null, storage.destination);
          destino((e1, dir) => {
            if (e1) return next(e1);
            storage.filename(req, { originalname: archivo.filename }, (e2, filename) => {
              if (e2) return next(e2);
              fs.mkdirSync(dir, { recursive: true });
              const full = path.join(dir, filename);
              fs.writeFileSync(full, archivo.data);
              req.file = { fieldname: campo, originalname: archivo.filename, mimetype: archivo.mimetype, filename, path: full, size: archivo.data.length };
              next();
            });
          });
        };
        if (fileFilter) fileFilter(req, { originalname: archivo.filename }, procesar);
        else procesar();
      };
    },
  };
}

multer.diskStorage = (opts) => opts;
export default multer;
